/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Matrix, Mul, Poly, PolyMatrix, PolyMatrixRing, Pow, QQ, Sym, ZZ, add, isUnsolved, mul, pow, pprintUseUnicode, rational, symbols } from '../../src';
import { at, pyItems, pyLen, pyRepr, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.polymatrix", () => {
  it("pm1.ring", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyMatrixRing(ZZ, [x]))).toBe('ZZ[x]');
  });
  it("v2.ring", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolyMatrixRing(QQ, [x]))).toBe('QQ[x]');
  });
  it("pm2*v2", () => {
    const x = new Sym('x');
    expect(sympyStr(PolyMatrix.fromList(1, 6, [pow(x, 2), 0, 1, pow(x, 3), 0, mul(-1, pow(x, 3))], [], new PolyMatrixRing(QQ, [x])).mul(PolyMatrix.fromList(6, 1, [1, 0, 0, 0, 0, 0], [], new PolyMatrixRing(QQ, [x]))))).toBe('PolyMatrix([[x**2]], ring=QQ[x])');
  });
  it("pm1*v1", () => {
    const x = new Sym('x');
    expect(sympyStr(PolyMatrix.fromList(2, 2, [pow(x, 2), mul(-1, x), pow(x, 3), add(-1, x)], [], new PolyMatrixRing(ZZ, [x])).mul(PolyMatrix.fromList(2, 2, [1, 0, -1, 0], [], new PolyMatrixRing(QQ, [x]))))).toBe('PolyMatrix([\n[    x**2 + x, 0],\n[x**3 - x + 1, 0]], ring=QQ[x])');
  });
  it("v1*pm1", () => {
    const x = new Sym('x');
    expect(sympyStr(PolyMatrix.fromList(2, 2, [1, 0, -1, 0], [], new PolyMatrixRing(QQ, [x])).mul(PolyMatrix.fromList(2, 2, [pow(x, 2), mul(-1, x), pow(x, 3), add(-1, x)], [], new PolyMatrixRing(ZZ, [x]))))).toBe('PolyMatrix([\n[ x**2, -x],\n[-x**2,  x]], ring=QQ[x])');
  });
});

